export PATH="$FIXTURE/bin:$PATH" GITHUB_ACTION_PATH="$FIXTURE" RUNNER_TEMP="$FIXTURE"
export GITHUB_OUTPUT="$FIXTURE/output" GITHUB_PATH="$FIXTURE/path" CALLS="$FIXTURE/calls" EXECUTIONS="$FIXTURE/executions"
