	const npm = readFileSync(new URL('../workflows/npm-release.yml', import.meta.url), 'utf8');
	assert.match(npm, /with: \{ go-version-file: go.mod \}/);
	assert.doesNotMatch(npm, /env\.GO|GO: "1\.27"/);
});

