	const diagnosticHeaders = new Set([
		'content-type',
		'date',
		'x-github-api-version-selected',
		'x-github-request-id',
		'retry-after',
	]);
	for (const line of head.split(/\r?\n/).slice(1)) {
		const colon = line.indexOf(':');
