type Outcome =
	| { kind: 'rejected'; phase: Rejection; message: string }
	| { kind: 'pending'; runId: number }
	| {
		kind: 'completed';
		run: Run;
		service: ServiceResult;
		runner: RunnerResult;
		environment: ObjectValue | null;
		runnerVersion: string | null;
	}
	| { kind: 'error'; message: string };
