			{ directory: 'packages/service', path: '../shared/ci.yml', expected: 'packages/shared/ci.yml' },
			{ directory: 'packages/service', path: join(workspace, '.github', 'ci.yml'), expected: '.github/ci.yml' },
		]
	) {
