#!/usr/bin/env bash
set -euo pipefail

# Use NUL-delimited paths and disable rename detection so moves cover both names.
git diff --name-only --no-renames -z "$1" "$2" -- | {
	tables=false
	readme=false
	while IFS= read -r -d '' path; do
		case "${path}" in
			.github/workflows/autofix.yml | tools/ci/autofix-inputs.bash | go.mod | go.sum)
				tables=true
				readme=true
				;;
			internal/action/* | internal/actioncatalog/* | internal/webhook/webhooks.gen.go | internal/webhook/generate/* | internal/webhook/payload/* | package.json | package-lock.json | internal/expression/context/* | internal/builtin/rule_events.go | internal/builtin/rule_expression.go | internal/rulecatalog/* | docs/rules.md | generate.go)
				tables=true
				;;
			.mise.toml | README.md | docs/screenshots/* | internal/documentation/check-readme/*)
				readme=true
				;;
			*) ;;
		esac
	done
	printf 'tables=%s\nreadme=%s\n' "${tables}" "${readme}"
} >>"${GITHUB_OUTPUT:?GITHUB_OUTPUT must name the step output file}"

